pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    function testFuzz_property(uint256 len, address from, address token) public {
        uint256 n = bound(len, 0, 3);
        address[] memory tos = new address[](n);
        uint256[] memory vs = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encode(i)))));
            vs[i] = 1;
        }
        bool ok;
        try c.transfer(from, token, tos, vs) { ok = true; } catch { ok = false; }
        assertTrue(!ok || n > 0, "empty recipient list must revert");
    }
}
